import{_ as a,c as t,o,ag as r}from"./chunks/framework.CoPVQkzc.js";const u=JSON.parse('{"title":"Database Support","description":"Supported databases and configuration","frontmatter":{"title":"Database Support","description":"Supported databases and configuration"},"headers":[],"relativePath":"engine/database_support.md","filePath":"engine/database_support.md","lastUpdated":1788476353000}'),s={name:"engine/database_support.md"};function n(i,e,d,c,l,p){return o(),t("div",null,e[0]||(e[0]=[r('<h1 id="database-support" tabindex="-1">Database Support <a class="header-anchor" href="#database-support" aria-label="Permalink to &quot;Database Support&quot;">​</a></h1><p>OIE ships with an embedded Apache Derby database by default. Derby works for trying things out, but you should switch to an external database for any production use.</p><h2 id="supported-databases" tabindex="-1">Supported databases <a class="header-anchor" href="#supported-databases" aria-label="Permalink to &quot;Supported databases&quot;">​</a></h2><ul><li><strong>Apache Derby</strong> (embedded, default)</li><li><strong>PostgreSQL</strong></li><li><strong>MySQL</strong></li><li><strong>Oracle</strong></li><li><strong>SQL Server</strong> (via jTDS or Microsoft driver)</li></ul><h2 id="changing-the-database" tabindex="-1">Changing the database <a class="header-anchor" href="#changing-the-database" aria-label="Permalink to &quot;Changing the database&quot;">​</a></h2><p>Database settings live in <code>conf/mirth.properties</code>. The key properties are:</p><ul><li><code>database</code> - The database type (<code>derby</code>, <code>postgres</code>, <code>mysql</code>, <code>oracle</code>, <code>sqlserver</code>)</li><li><code>database.url</code> - JDBC connection URL</li><li><code>database.username</code> / <code>database.password</code> - Credentials (not needed for Derby)</li><li><code>database.driver</code> - Override the default JDBC driver class if needed</li></ul><p>The properties file contains commented-out examples for each supported database. Uncomment and edit the ones you need.</p><h2 id="connection-pool-settings" tabindex="-1">Connection pool settings <a class="header-anchor" href="#connection-pool-settings" aria-label="Permalink to &quot;Connection pool settings&quot;">​</a></h2><p>The properties file also includes settings for connection pool sizing:</p><ul><li><code>database.max-connections</code> - Max connections for read/write operations (default: 20)</li><li><code>database-readonly.max-connections</code> - Max connections for read-only operations (default: 20)</li></ul><p>Read-write splitting is enabled by default (<code>database.enable-read-write-split = true</code>), which separates read-only queries onto their own connection pool. By default the read-only pool uses the same connection information as the main pool, but you can point it at a different host (e.g., a read replica) using the <code>database-readonly.*</code> properties.</p><h2 id="startup-retry" tabindex="-1">Startup retry <a class="header-anchor" href="#startup-retry" aria-label="Permalink to &quot;Startup retry&quot;">​</a></h2><p>If the database is unavailable when the server starts, OIE can retry the connection. This is controlled by:</p><ul><li><code>database.connection.maxretry</code> - Number of retry attempts (default: 2)</li><li><code>database.connection.retrywaitinmilliseconds</code> - Wait between retries in ms (default: 10000)</li></ul><h2 id="database-drivers-for-connectors" tabindex="-1">Database drivers for connectors <a class="header-anchor" href="#database-drivers-for-connectors" aria-label="Permalink to &quot;Database drivers for connectors&quot;">​</a></h2><p>The file <code>conf/dbdrivers.xml</code> defines the database drivers available in the <strong>Database Reader</strong> and <strong>Database Writer</strong> connectors. These are separate from the server&#39;s own database connection. They control which databases your channels can connect to.</p><h2 id="schema-and-migration" tabindex="-1">Schema and migration <a class="header-anchor" href="#schema-and-migration" aria-label="Permalink to &quot;Schema and migration&quot;">​</a></h2><p>OIE creates and updates its database schema automatically on startup. After an upgrade, check <strong>Settings &gt; Database Tasks</strong> in the Administrator for optional cleanup tasks such as removing old tables from prior versions or adding missing indexes.</p>',19)]))}const b=a(s,[["render",n]]);export{u as __pageData,b as default};
